const tau = Math.PI * 2;
const cellW = width / Math.max(1, columns);
const cellH = height / Math.max(1, rows);
const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
const mod = (value, size) => ((value % size) + size) % size;
